<?php

namespace App\Services\Email;

use App\Enums\EmailFormat;

/**
 * One outbound email the dispatcher asks the transport to deliver.
 *
 * The reference is generated by OmniCast before the message is submitted, so a
 * bounce or complaint receipt can always be matched to the message even when
 * the mail server has not assigned a message id yet.
 *
 * Attachments are storage references rather than bytes, so the same message can
 * be handed to an SMTP transport or an HTTP gateway without the file ever being
 * copied into a queue payload.
 */
final class OutboundEmail
{
    /**
     * @param  list<OutboundAttachment>  $attachments
     */
    public function __construct(
        public readonly string $reference,
        public readonly string $to,
        public readonly string $from,
        public readonly string $subject,
        public readonly string $body,
        public readonly EmailFormat $format = EmailFormat::Html,
        public readonly ?string $fromName = null,
        public readonly array $attachments = [],
    ) {}

    /**
     * Whether the message carries files.
     */
    public function hasAttachments(): bool
    {
        return $this->attachments !== [];
    }

    /**
     * The attachments whose bytes are still on disk.
     *
     * @return list<OutboundAttachment>
     */
    public function deliverableAttachments(): array
    {
        return array_values(array_filter(
            $this->attachments,
            fn (OutboundAttachment $attachment): bool => $attachment->exists(),
        ));
    }

    /**
     * Whether the authored body carries markup.
     */
    public function isHtml(): bool
    {
        return $this->format->isHtml();
    }

    /**
     * The HTML part of the message, when the broadcast is authored in HTML.
     */
    public function htmlBody(): ?string
    {
        return $this->isHtml() ? $this->body : null;
    }

    /**
     * The plain-text part of the message.
     *
     * An HTML broadcast is always sent with a generated text alternative, so a
     * client that refuses HTML still shows the message instead of an empty body.
     */
    public function textBody(): string
    {
        if (! $this->isHtml()) {
            return $this->body;
        }

        $text = preg_replace('/<(br|\/p|\/div|\/li|\/h[1-6])\s*\/?>/i', "\n", $this->body) ?? $this->body;
        $text = strip_tags($text);
        $text = html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8');
        $text = preg_replace('/[ \t]+/', ' ', $text) ?? $text;
        $text = preg_replace('/\n{3,}/', "\n\n", $text) ?? $text;

        return trim($text);
    }

    /**
     * The signed URL a provider posts the delivery feedback to.
     *
     * A provider that accepts a per-message callback (generic JSON gateways) gets
     * the reference and its signature in the query string, so the receipt can be
     * verified without a request body.
     */
    public function deliveryUrl(): ?string
    {
        $secret = (string) config('email.webhook.secret');

        if ($secret === '') {
            return null;
        }

        return route('webhooks.email', [
            'reference' => $this->reference,
            'sig' => hash_hmac('sha256', $this->reference, $secret),
        ]);
    }

    /**
     * The recipient in the form a log line may show it.
     */
    public function maskedTo(): string
    {
        $parts = explode('@', $this->to, 2);

        if (count($parts) !== 2) {
            return '***';
        }

        $local = $parts[0];
        $visible = mb_substr($local, 0, 1);

        return $visible.'***@'.$parts[1];
    }
}
